<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('projects.manage');$pdo=db();$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT d.*,c.company_name FROM deals d LEFT JOIN clients c ON c.id=d.client_id WHERE d.id=?");$q->execute([$id]);$d=$q->fetch();if(!$d){http_response_code(404);exit('Negocio no encontrado.');}if($d['status']!=='won'){flash('error','Solo los negocios ganados pueden convertirse en proyecto.');redirect('deal_view.php?id='.$id);}$check=$pdo->prepare('SELECT id FROM projects WHERE deal_id=? LIMIT 1');$check->execute([$id]);$existing=(int)$check->fetchColumn();if($existing)redirect('project_view.php?id='.$existing);$code='PRJ-'.date('Y').'-'.str_pad((string)$id,4,'0',STR_PAD_LEFT);$pdo->prepare('INSERT INTO projects(client_id,deal_id,owner_user_id,name,code,status,health,priority,start_date,due_date,budget,currency,billing_model,created_by) VALUES (?,?,?,?,?,\'planning\',\'on_track\',\'normal\',CURDATE(),?,?,?,?,?)')->execute([(int)$d['client_id']?:null,$id,(int)$d['owner_user_id']?:null,$d['title'],$code,$d['expected_close_date']?:null,(float)$d['amount'],$d['currency'],'fixed',(int)$_SESSION['user_id']]);$pid=(int)$pdo->lastInsertId();if($d['owner_user_id'])$pdo->prepare("INSERT IGNORE INTO project_members(project_id,user_id,role_name) VALUES (?,?, 'Project Manager')")->execute([$pid,(int)$d['owner_user_id']]);flash('success','Negocio convertido en proyecto.');redirect('project_view.php?id='.$pid);
